<template>
  <div class="app-container gift-bi">
    <header class="page-head"><div><h2>礼品经营 BI</h2><p>礼品成本、订单使用和库存风险集中分析。</p></div><div class="head-actions"><el-button icon="Box" @click="goInventory">库存管理</el-button><el-button icon="Refresh" :loading="loading" title="刷新" @click="load" /></div></header>
    <section class="filter-strip"><el-button-group><el-button v-for="item in presets" :key="item.value" :type="preset===item.value?'primary':''" @click="setPreset(item.value)">{{ item.label }}</el-button></el-button-group><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" @change="preset='';load()" /><span class="period-note">统计所选日期内的礼品记录</span></section>

    <section v-loading="loading" class="metric-grid">
      <article><span>礼品总成本</span><strong class="money">¥{{ money(summary.giftCost) }}</strong><small :class="deltaClass(summary.giftCost,previous.giftCost)">{{ deltaText(summary.giftCost,previous.giftCost) }}</small></article>
      <article><span>送出礼品</span><strong>{{ integer(summary.giftQuantity) }}<em>件</em></strong><small :class="deltaClass(summary.giftQuantity,previous.giftQuantity)">{{ deltaText(summary.giftQuantity,previous.giftQuantity) }}</small></article>
      <article><span>礼品订单</span><strong>{{ integer(summary.giftOrders) }}<em>单</em></strong><small>共处理 {{ integer(summary.handledOrders) }} 单</small></article>
      <article><span>订单含礼品率</span><strong>{{ giftRate }}<em>%</em></strong><small>有礼品订单 / 已处理订单</small></article>
      <article><span>平均每单成本</span><strong>¥{{ averageCost }}</strong><small>按有礼品订单计算</small></article>
      <article class="risk"><span>库存风险</span><strong>{{ riskCount }}<em>种</em></strong><small>其中零库存 {{ integer(inventorySummary.zeroCount) }} 种</small></article>
    </section>

    <div class="primary-grid">
      <section class="panel trend-panel"><div class="panel-head"><div><strong>每日礼品成本</strong><span>观察投入变化，点击日期查看订单</span></div><b>¥{{ money(summary.giftCost) }}</b></div><div v-if="trendRows.length" class="trend-list"><button v-for="row in trendRows" :key="row.groupName" @click="goLedger({beginDate:row.groupName,endDate:row.groupName})"><time>{{ shortDate(row.groupName) }}</time><div class="bar"><i :style="{width:`${barWidth(row.giftCost,trendMax)}%`}" /></div><span>{{ integer(row.giftQuantity) }} 件</span><strong>¥{{ money(row.giftCost) }}</strong></button></div><el-empty v-else description="所选日期暂无礼品数据" :image-size="72" /></section>
      <section class="panel structure-panel"><div class="panel-head"><div><strong>订单结构</strong><span>礼品覆盖与投入水平</span></div></div><div class="rate-ring" :style="{'--rate':`${Math.min(giftRate,100)*3.6}deg`}"><div><strong>{{ giftRate }}%</strong><span>订单含礼品</span></div></div><dl><div><dt>已处理订单</dt><dd>{{ integer(summary.handledOrders) }}</dd></div><div><dt>无礼品订单</dt><dd>{{ integer(noGiftOrders) }}</dd></div><div><dt>平均每单件数</dt><dd>{{ averageQuantity }}</dd></div><div><dt>成本占订单金额</dt><dd>{{ orderCostRate }}%</dd></div></dl><el-button link type="primary" icon="ArrowRight" @click="goLedger()">查看礼品记录</el-button></section>
    </div>

    <section class="panel ranking-panel"><div class="panel-head"><div><strong>礼品消耗排行</strong><span>成本、数量与当前库存放在一起判断</span></div><el-segmented v-model="rankMode" :options="rankOptions" /></div><el-table :data="rankedGifts" stripe size="small" @row-click="row=>goLedger({giftName:row.groupName})"><el-table-column type="index" label="#" width="52" /><el-table-column prop="groupName" label="礼品" min-width="210" show-overflow-tooltip /><el-table-column prop="giftQuantity" label="送出件数" width="100" align="right" /><el-table-column prop="orderCount" label="涉及订单" width="100" align="right" /><el-table-column label="累计成本" width="130" align="right"><template #default="{row}"><strong class="money">¥{{ money(row.giftCost) }}</strong></template></el-table-column><el-table-column label="成本占比" min-width="150"><template #default="{row}"><div class="share-cell"><el-progress :percentage="costShare(row.giftCost)" :stroke-width="7" :show-text="false" /><span>{{ costShare(row.giftCost) }}%</span></div></template></el-table-column><el-table-column label="当前库存" width="120" align="right"><template #default="{row}"><span :class="stockClass(stockFor(row))">{{ integer(stockFor(row).stockQty) }} 件</span></template></el-table-column><el-table-column label="库存状态" width="110"><template #default="{row}"><el-tag size="small" :type="stockTag(stockFor(row))">{{ stockLabel(stockFor(row)) }}</el-tag></template></el-table-column><template #empty><el-empty description="暂无礼品消耗数据" :image-size="64" /></template></el-table></section>

    <section class="panel warning-panel"><div class="panel-head"><div><strong>需要处理的库存</strong><span>零库存无法继续录入订单，低库存建议及时补充</span></div><el-button link type="primary" icon="ArrowRight" @click="goInventory">去处理库存</el-button></div><div v-if="warningRows.length" class="warning-list"><button v-for="row in warningRows" :key="row.giftId" @click="goInventory(row.giftCode)"><div><strong>{{ row.giftName }}</strong><span>{{ row.giftCode }}</span></div><b :class="Number(row.stockQty)===0?'danger':'warning'">{{ integer(row.stockQty) }} 件</b><small>安全库存 {{ integer(row.safetyQty) }}</small><el-tag :type="Number(row.stockQty)===0?'danger':'warning'">{{ Number(row.stockQty)===0?'立即补货':'低于安全库存' }}</el-tag></button></div><el-empty v-else description="库存状态正常" :image-size="64" /></section>
  </div>
</template>

<script setup name="GiftSummary">
import { getGiftInventorySummary, getGiftSummary, listGiftInventory } from '@/api/live/gift'
import { useRouter } from 'vue-router'
const router=useRouter(),iso=date=>date.toISOString().slice(0,10),now=new Date(),today=iso(now),monthStart=iso(new Date(now.getFullYear(),now.getMonth(),1))
const presets=[{label:'今天',value:'today'},{label:'近7天',value:'week'},{label:'本月',value:'month'},{label:'全部',value:'all'}],rankOptions=[{label:'按成本',value:'cost'},{label:'按数量',value:'quantity'}]
const summary=ref({}),previous=ref({}),trendRows=ref([]),giftRows=ref([]),inventoryRows=ref([]),inventorySummary=ref({}),dates=ref([monthStart,today]),preset=ref('month'),rankMode=ref('cost'),loading=ref(false)
const money=v=>Number(v||0).toFixed(2),integer=v=>Number(v||0).toLocaleString('zh-CN'),ratio=(v,t)=>t?Math.round(Number(v||0)*1000/Number(t))/10:0
const giftRate=computed(()=>ratio(summary.value.giftOrders,summary.value.handledOrders)),orderCostRate=computed(()=>ratio(summary.value.giftCost,summary.value.orderAmount)),averageCost=computed(()=>money(Number(summary.value.giftCost||0)/Math.max(Number(summary.value.giftOrders||0),1))),averageQuantity=computed(()=>(Number(summary.value.giftQuantity||0)/Math.max(Number(summary.value.giftOrders||0),1)).toFixed(1)),noGiftOrders=computed(()=>Math.max(0,Number(summary.value.handledOrders||0)-Number(summary.value.giftOrders||0))),riskCount=computed(()=>integer(Number(inventorySummary.value.lowCount||0)+Number(inventorySummary.value.zeroCount||0))),trendMax=computed(()=>Math.max(...trendRows.value.map(r=>Number(r.giftCost||0)),1)),warningRows=computed(()=>inventorySummary.value.lowStock||[])
const rankedGifts=computed(()=>[...giftRows.value].sort((a,b)=>rankMode.value==='quantity'?Number(b.giftQuantity)-Number(a.giftQuantity):Number(b.giftCost)-Number(a.giftCost)))
function baseQuery(){return{beginDate:dates.value?.[0],endDate:dates.value?.[1]}}
function previousRange(){if(!dates.value?.length)return{};const start=new Date(`${dates.value[0]}T00:00:00`),end=new Date(`${dates.value[1]}T00:00:00`),days=Math.max(1,Math.round((end-start)/86400000)+1),previousEnd=new Date(start.getTime()-86400000),previousStart=new Date(previousEnd.getTime()-(days-1)*86400000);return{beginDate:iso(previousStart),endDate:iso(previousEnd)}}
async function load(){loading.value=true;try{const q=baseQuery(),[main,trend,gifts,old,stock,stocks]=await Promise.all([getGiftSummary({...q,groupBy:'date'}),getGiftSummary({...q,groupBy:'date'}),getGiftSummary({...q,groupBy:'gift'}),getGiftSummary({...previousRange(),groupBy:'date'}),getGiftInventorySummary({}),listGiftInventory({status:'0'})]);summary.value=main.data||{};trendRows.value=(trend.data?.groups||[]).slice().reverse();giftRows.value=gifts.data?.groups||[];previous.value=old.data||{};inventorySummary.value=stock.data||{};inventoryRows.value=stocks.data||[]}finally{loading.value=false}}
function setPreset(v){preset.value=v;if(v==='today')dates.value=[today,today];if(v==='week')dates.value=[iso(new Date(Date.now()-6*86400000)),today];if(v==='month')dates.value=[monthStart,today];if(v==='all')dates.value=[];load()}
function deltaText(c,p){c=Number(c||0);p=Number(p||0);if(!p)return c?'新增':'无变化';const d=Math.round((c-p)*1000/p)/10;return d>0?`↑ ${d}% 较上期`:d<0?`↓ ${Math.abs(d)}% 较上期`:'无变化'}function deltaClass(c,p){return Number(c||0)>Number(p||0)?'up':Number(c||0)<Number(p||0)?'down':'flat'}
function barWidth(v,max){return Math.max(2,Math.round(Number(v||0)*100/max))}function shortDate(v){return String(v||'').slice(5)}function costShare(v){return ratio(v,summary.value.giftCost)}function stockFor(row){return inventoryRows.value.find(item=>item.giftName===row.groupName)||{stockQty:0,safetyQty:0,stockStatus:'zero'}}function stockClass(row){return row.stockStatus==='zero'?'danger':row.stockStatus==='low'?'warning':'normal'}function stockTag(row){return row.stockStatus==='zero'?'danger':row.stockStatus==='low'?'warning':'success'}function stockLabel(row){return row.stockStatus==='zero'?'零库存':row.stockStatus==='low'?'低库存':'正常'}
function goLedger(extra={}){router.push({path:'/live-ops/gift/giftLedger',query:{...baseQuery(),...extra}})}function goInventory(keyword){router.push({path:'/live-ops/gift/giftAdmin',query:{section:'inventory',...(keyword?{keyword}:{})}})}
onMounted(load)
</script>

<style scoped>
.gift-bi{max-width:1600px}.page-head,.head-actions,.filter-strip,.panel-head,.trend-list button,.share-cell{display:flex;align-items:center}.page-head,.panel-head{justify-content:space-between;gap:16px}.page-head h2{margin:0 0 4px;font-size:22px}.page-head p,.panel-head span,.period-note,.metric-grid small{margin:0;color:#6b7280;font-size:12px}.head-actions,.filter-strip{gap:10px}.filter-strip{flex-wrap:wrap;padding:18px 0;border-bottom:1px solid #e5e7eb}.period-note{margin-left:auto}.metric-grid{display:grid;grid-template-columns:repeat(6,1fr);margin-top:16px;border:1px solid #e5e7eb}.metric-grid article{display:flex;min-width:0;min-height:108px;flex-direction:column;gap:7px;padding:15px;border-right:1px solid #e5e7eb;background:#fff}.metric-grid article:last-child{border:0}.metric-grid article.risk{background:#fff7ed}.metric-grid strong{font-size:23px}.metric-grid em{margin-left:3px;font-size:12px;font-style:normal;font-weight:400}.up,.danger{color:#dc2626}.down,.normal{color:#16a34a}.flat{color:#6b7280}.warning{color:#d97706}.money{color:#c2410c}.primary-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.65fr);gap:14px;margin-top:14px}.panel{border:1px solid #e2e5e9;background:#fff}.panel-head{min-height:62px;padding:12px 16px;border-bottom:1px solid #edf0f2}.panel-head>div{display:flex;flex-direction:column;gap:3px}.panel-head>b{color:#c2410c}.trend-list{display:flex;flex-direction:column;padding:9px 16px}.trend-list button{gap:10px;padding:8px 0;border:0;border-bottom:1px solid #f0f2f4;background:transparent;cursor:pointer}.trend-list time{width:48px;color:#6b7280}.trend-list .bar{height:8px;flex:1;border-radius:4px;background:#f2f3f5;overflow:hidden}.trend-list .bar i{display:block;height:100%;border-radius:4px;background:#f26b21}.trend-list span{width:65px;color:#6b7280;text-align:right}.trend-list strong{width:88px;text-align:right}.structure-panel{padding-bottom:14px}.structure-panel .panel-head{margin-bottom:14px}.rate-ring{position:relative;display:grid;width:138px;height:138px;margin:8px auto 18px;border-radius:50%;background:conic-gradient(#f26b21 var(--rate),#eef0f3 0);place-items:center}.rate-ring:before{position:absolute;width:106px;height:106px;border-radius:50%;background:#fff;content:''}.rate-ring div{z-index:1;display:flex;flex-direction:column;align-items:center}.rate-ring strong{font-size:26px}.rate-ring span{color:#6b7280;font-size:11px}.structure-panel dl{display:grid;grid-template-columns:1fr 1fr;margin:0 18px}.structure-panel dl div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eef0f2}.structure-panel dt{color:#6b7280;font-size:12px}.structure-panel dd{margin:0;font-weight:600}.structure-panel>.el-button{margin:10px 18px 0}.ranking-panel,.warning-panel{margin-top:14px}.ranking-panel :deep(.el-table__row){cursor:pointer}.share-cell{gap:8px}.share-cell .el-progress{flex:1}.share-cell span{width:42px;text-align:right}.warning-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:1px;background:#e5e7eb}.warning-list button{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px 12px;padding:13px 16px;border:0;background:#fff;text-align:left;cursor:pointer}.warning-list button:hover{background:#fffaf7}.warning-list div{min-width:0}.warning-list div strong,.warning-list div span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.warning-list div span,.warning-list small{color:#6b7280;font-size:11px}.warning-list b{font-size:18px}.warning-list .el-tag{width:max-content}@media(max-width:1100px){.metric-grid{grid-template-columns:repeat(3,1fr)}.primary-grid{grid-template-columns:1fr}}@media(max-width:720px){.metric-grid{grid-template-columns:repeat(2,1fr)}.period-note{display:none}.filter-strip>*{width:100%!important}.trend-list span{display:none}}@media(max-width:430px){.metric-grid{grid-template-columns:1fr}}
</style>
